const crearPlantillaBorrador = async () => {
  const empresaId = prompt('EmpresaID para la plantilla:');
  if (!empresaId) return;
  const codigo = prompt('Codigo de plantilla:');
  if (!codigo) return;
  const nombre = prompt('Nombre de plantilla:');
  if (!nombre) return;
  const insumoCodigo = prompt('SKU/codigo de lonja base:') || null;
  const insumoNombre = prompt('Nombre de lonja base:') || insumoCodigo || 'Lonja base';
  try {
    await api.post('/tablajeria/plantillas', {
      empresa_id: empresaId,
      codigo_plantilla: codigo,
      nombre_plantilla: nombre,
      insumo_base_codigo: insumoCodigo,
      insumo_base_nombre: insumoNombre,
      unidad_base_codigo: 'KG',
      cantidad_base_estandar: 1,
      detalles: []
    });
    toast.success('Plantilla creada en borrador');
    fetchPlantillas();
  } catch (err) {
    toast.error(err.response?.data?.detail || 'Error creando plantilla');
  }
};

const editarPlantillaBasica = async () => {
  if (!selectedPlantilla?.PlantillaID) {
    toast.error('Selecciona una plantilla');
    return;
  }
  const nuevoNombre = prompt('Nuevo nombre:', selectedPlantilla.NombrePlantilla || '');
  if (!nuevoNombre) return;
  const rendimiento = prompt('Rendimiento esperado %:', selectedPlantilla.RendimientoEsperadoPorcentaje || '');
  const merma = prompt('Merma esperada %:', selectedPlantilla.MermaEsperadaPorcentaje || '');
  const payload = { nombre_plantilla: nuevoNombre };
  if (rendimiento) payload.rendimiento_esperado_porcentaje = Number(rendimiento);
  if (merma) payload.merma_esperada_porcentaje = Number(merma);
  try {
    await api.put(`/tablajeria/plantillas/${selectedPlantilla.PlantillaID}`, payload);
    toast.success('Plantilla actualizada');
    fetchPlantillas();
    fetchPlantillaDetalle(selectedPlantilla.PlantillaID);
  } catch (err) {
    toast.error(err.response?.data?.detail || 'Error editando plantilla');
  }
};

const duplicarPlantillaSeleccionada = async () => {
  if (!selectedPlantilla?.PlantillaID) {
    toast.error('Selecciona una plantilla');
    return;
  }
  const codigo = prompt('Codigo de nueva version:', `${selectedPlantilla.CodigoPlantilla || 'PLANTILLA'}-V${Number(selectedPlantilla.VersionActual || 1) + 1}`);
  if (!codigo) return;
  const nombre = prompt('Nombre de nueva version:', `${selectedPlantilla.NombrePlantilla || 'Plantilla'} v${Number(selectedPlantilla.VersionActual || 1) + 1}`);
  if (!nombre) return;
  try {
    const response = await api.post(`/tablajeria/plantillas/${selectedPlantilla.PlantillaID}/duplicar`, {
      codigo_plantilla: codigo,
      nombre_plantilla: nombre,
      descripcion: selectedPlantilla.Descripcion || null,
      motivo_version: 'Version creada desde UAT frontend R3B'
    });
    toast.success('Version de plantilla creada');
    fetchPlantillas();
    if (response.data?.plantilla_id) fetchPlantillaDetalle(response.data.plantilla_id);
  } catch (err) {
    toast.error(err.response?.data?.detail || 'Error duplicando plantilla');
  }
};

