const getLonja = (lonja, keys) => {
  for (const key of keys) {
    if (lonja?.[key] !== undefined && lonja?.[key] !== null && lonja?.[key] !== '') return lonja[key];
  }
  return '';
};

const fetchLonjasDisponibles = async () => {
  try {
    const params = new URLSearchParams({ limit: '100' });
    if (formCrear.empresa_id) params.append('empresa_id', formCrear.empresa_id);
    if (formCrear.unidad_negocio_pk) params.append('unidad_negocio_pk', formCrear.unidad_negocio_pk);
    if (formCrear.almacen_origen_id) params.append('almacen_origen_id', formCrear.almacen_origen_id);
    const response = await api.get(`/tablajeria/lonjas-disponibles?${params}`);
    setLonjasDisponibles(response.data.lonjas || []);
    toast.success(`Lonjas disponibles: ${response.data.total || 0}`);
  } catch (err) {
    toast.error(err.response?.data?.detail || 'Error cargando lonjas disponibles');
  }
};

const seleccionarLonja = (lonjaId) => {
  const lonja = lonjasDisponibles.find((item) => String(getLonja(item, ['lonja_id', 'LonjaID', 'LoteID', 'id'])) === String(lonjaId));
  if (!lonja) {
    setFormCrear({ ...formCrear, lonja_id: lonjaId });
    return;
  }
  const pesoKg = getLonja(lonja, ['peso_kg', 'PesoKg', 'PesoKG', 'CantidadKg', 'CantidadBaseKg']);
  setFormCrear({
    ...formCrear,
    empresa_id: formCrear.empresa_id || getLonja(lonja, ['empresa_id', 'EmpresaID']),
    unidad_negocio_pk: formCrear.unidad_negocio_pk || getLonja(lonja, ['unidad_negocio_pk', 'UnidadNegocioID']),
    almacen_origen_id: formCrear.almacen_origen_id || getLonja(lonja, ['almacen_origen_id', 'AlmacenOrigenID', 'AlmacenID']),
    lonja_id: lonjaId,
    lonja_codigo: getLonja(lonja, ['insumo_base_codigo', 'InsumoBaseCodigo', 'ProductoCodigo', 'Codigo']),
    lonja_nombre: getLonja(lonja, ['insumo_base_nombre', 'InsumoBaseNombre', 'ProductoNombre', 'Nombre']),
    lonja_peso_kg: pesoKg,
    lonja_costo_total: getLonja(lonja, ['costo_total', 'CostoTotal', 'ImporteCosto']),
    lote_insumo: getLonja(lonja, ['lote_insumo', 'LoteInsumo', 'LoteProveedor', 'LoteInterno']),
    cantidad_base_planeada: pesoKg
  });
};

